import re
from html.parser import HTMLParser
s = '<div>outer <div>inner</div> tail</div>'
print('greedy:', re.findall(r'<div>(.*)</div>', s))
print('lazy:', re.findall(r'<div>(.*?)</div>', s))
class Counter(HTMLParser):
    def __init__(self):
        super().__init__()
        self.depth = 0
        self.maxdepth = 0
    def handle_starttag(self, tag, attrs):
        if tag == 'div':
            self.depth += 1
            self.maxdepth = max(self.maxdepth, self.depth)
    def handle_endtag(self, tag):
        if tag == 'div':
            self.depth -= 1
c = Counter()
c.feed(s)
print('parser max depth:', c.maxdepth, '| balanced at end:', c.depth == 0)
